from datetime import datetime, timedelta
from typing import Dict, List, Optional


class Appointment:
    def __init__(self, appointment_id: int, patient: str, doctor: str, start: datetime, end: datetime):
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.slot_blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start must be before end.")

        # Requirement 4: A patient can have at most one upcoming appointment;
        # booking another one while the first is still upcoming raises ValueError.
        # An appointment is "upcoming" relative to `now` if it has not yet started (or ended)
        # and has not been cancelled.
        for appt in self._appointments.values():
            if appt.patient == patient and not appt.cancelled:
                if appt.start > now:
                    raise ValueError(f"Patient '{patient}' already has an upcoming appointment.")

        # Requirement 3: Booking an appointment that overlaps another appointment of the same doctor raises ValueError.
        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor '{doctor}' is not free between {start} and {end}.")

        appt_id = self._next_id
        self._next_id += 1

        self._appointments[appt_id] = Appointment(appt_id, patient, doctor, start, end)
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an existing appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.cancelled:
            return

        appt.cancelled = True

        # Requirement 2: Cancelling an appointment less than 24 hours before its start
        # does not free the time slot; the slot stays blocked.
        if appt.start - now < timedelta(hours=24):
            appt.slot_blocked = True
        else:
            appt.slot_blocked = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start must be before end.")

        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.slot_blocked:
                # Requirement 1: Appointments that only touch do not overlap.
                # Overlap condition: max(start1, start2) < min(end1, end2)
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True
